SELECT DISTINCT md.chembl_id AS compound_chembl_id, cs.canonical_smiles FROM molecule_dictionary md JOIN activities a ON md.molregno = a.molregno JOIN assays ass ON a.assay_id = ass.assay_id JOIN target_dictionary td ON ass.tid = td.tid JOIN compound_structures cs ON md.molregno = cs.molregno WHERE ass.assay_organism = 'Homo sapiens' AND td.chembl_id = 'CHEMBL1827' ORDER BY md.chembl_id, cs.canonical_smiles
